{
  "results": [
    {
      "criterion_id": "criterion-1",
      "passed": true,
      "evidence": [
        "final_message 的“事实、假设与缺口”表分别列出已知事实、工作假设和待确认规则。",
        "final_message 明确写明接口字段、角色权限矩阵和支付最终状态规则未提供，并声明不自行指定字段名、状态名或错误码。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-2",
      "passed": true,
      "evidence": [
        "final_message 的 T01 覆盖登录、加购、下单、沙箱支付、回调和订单查询。",
        "T03、T04 覆盖顺序及并发重复回调；T07、T08 覆盖延迟、超时及状态乱序。",
        "T05、T06、T09、T10 分别覆盖重复提交、金额篡改、订单归属隔离和非法回调。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-3",
      "passed": true,
      "evidence": [
        "final_message 将风险分为 P0/P1，并给出 0–30 分钟的分段执行顺序。",
        "final_message 明确将 P1 留待有余量时执行，将超出窗口的 T07/T08 标为未验证的 P0，并说明生产支付、长期补偿及其他场景仍有风险。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-4",
      "passed": true,
      "evidence": [
        "final_message 的用例表为每个 T01–T15 列出前置条件、操作、预期判断和关键证据。",
        "例如 T03 要求已有合法支付和可重放事件，规定连续发送同一回调、检查无重复业务副作用，并保留响应、日志及快照。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-5",
      "passed": true,
      "evidence": [
        "final_message 开头声明测试尚未执行，结尾再次说明当前所有用例均未执行。",
        "final_message 列出重复扣款、越权成功等停止条件，以及规则缺失、环境不明和时间到期时的处理方式。",
        "final_message 要求先补齐契约和权限规则，再补测 P0；未声称业务或发布验证已经通过。"
      ],
      "failures": []
    }
  ]
}
